source_patch:
#if RE4DC_SS_RESTORE_VALIDATE_FIRST
    // A bad restore must halt before thaw or motion recount dereferences it.
    // Keep suspension and backing ownership intact for the failure diagnostic.
    if (h != open_hash) re4dc_missing("sub screen backing corrupted while the screen was open");
#endif

actual_missing.body:
    // Keep the first failure before the intentional sleep loop hides it from
    // the watchdog. The hook is absent when CRASH_SCREEN is disabled.
    if (re4dc_crash_screen_missing) re4dc_crash_screen_missing(name);
    re4dc_log("RE4DC MISSING: %s called; halting\n", name);
#if RE4DC_VMU_DEBUG_SLOT
    re4dc_dbgslot_ring(2, (unsigned) name, 0);
#endif
    fflush(stdout);
    for (;;) {
        thd_sleep(1000);
    }
